#!/usr/bin/env python3
"""Applies the patches recorded in patches.md to the Thrift compiler's Rust output and writes
src/gen/mod.rs and src/gen/methods.rs. Run by regen.sh; fails loudly when the compiler output no
longer has the shape a patch expects, so a compiler change cannot slip through unpatched."""
import os
import re
import sys

PROCESSOR = re.compile(r"^impl <H: (\w+)SyncHandler> TProcessor for \w+SyncProcessor<H> \{$", re.M)
ARM = re.compile(r'"([^"]+)" => \{\s*self\.process_(\w+)\(')

HEADER = """\
// Generated by regen.sh from idl/ (see patches.md); do not edit.
#![cfg_attr(rustfmt, rustfmt_skip)]
"""

METHODS_PREAMBLE = HEADER + """
//! Every service method's wire name with round trips of its `*Args` and `*Result` structs, read
//! from the generated processors' dispatch.

use thrift::protocol::{TInputProtocol, TOutputProtocol};

/// Decodes one message body from the input protocol and encodes it again to the output.
pub(crate) type RoundTripFn = fn(&mut dyn TInputProtocol, &mut dyn TOutputProtocol) -> Result<(), Failure>;

/// Where a body round trip failed.
#[derive(Debug)]
pub(crate) enum Failure {
    Decode(thrift::Error),
    Encode(thrift::Error),
}

/// One service method: its wire name and the round trips of its call and reply bodies.
pub(crate) struct Method {
    pub(crate) service: &'static str,
    pub(crate) name: &'static str,
    pub(crate) args: RoundTripFn,
    pub(crate) result: RoundTripFn,
}

fn roundtrip<T>(
    i: &mut dyn TInputProtocol,
    o: &mut dyn TOutputProtocol,
    read: fn(&mut dyn TInputProtocol) -> thrift::Result<T>,
    write: fn(&T, &mut dyn TOutputProtocol) -> thrift::Result<()>,
) -> Result<(), Failure> {
    let value = read(i).map_err(Failure::Decode)?;
    write(&value, o).map_err(Failure::Encode)
}

pub(crate) static METHODS: &[Method] = &[
"""


def replace_exactly(text, old, new, count, what):
    found = text.count(old)
    if found != count:
        sys.exit(f"postprocess: expected {count} x {old!r} in {what}, found {found}")
    return text.replace(old, new)


def services(module, text):
    """[(service, wire method name, args struct, result struct)] for every processor in a module."""
    out = []
    for m in PROCESSOR.finditer(text):
        service = m.group(1)
        body = text[m.end():text.index("\n    };\n", m.end())]
        for name, snake in ARM.findall(body):
            fn = re.search(
                rf"pub fn process_{snake}<H: {service}SyncHandler>\([^\n]*\n\s*"
                rf"let (?:args|_) = (\w+)::read_from_in_protocol\(i_prot\)\?;",
                text,
            )
            if not fn:
                sys.exit(f"postprocess: {module}: no process function for {service}.{name}")
            args = fn.group(1)
            result = args[: -len("Args")] + "Result"
            for struct in (args, result):
                if f"\nstruct {struct} {{\n" not in text:
                    sys.exit(f"postprocess: {module}: struct {struct} for {service}.{name} missing")
            out.append((service, name, args, result))
    return out


def expose(text, struct):
    """Makes a per-method struct, its fields and its inherent methods public."""
    def fields(m):
        return m.group(1) + re.sub(r"(?m)^  (\w+): ", r"  pub \1: ", m.group(2)) + "}"
    text, n = re.subn(rf"\nstruct ({struct}) \{{\n", rf"\npub struct \1 {{\n", text)
    if n != 1:
        sys.exit(f"postprocess: struct {struct} found {n} times")
    text = re.sub(rf"(\npub struct {struct} \{{\n)(.*?)\}}", fields, text, count=1, flags=re.S)
    start = text.index(f"\nimpl {struct} {{\n")
    end = text.index("\n}\n", start)
    block = re.sub(r"(?m)^  fn ", "  pub fn ", text[start:end])
    return text[:start] + block + text[end:]


def main(gen):
    modules = sorted(f[:-3] for f in os.listdir(gen) if f.endswith(".rs"))
    if len(modules) != 27:
        sys.exit(f"postprocess: expected 27 generated modules, found {len(modules)}")
    table = []
    for module in modules:
        path = os.path.join(gen, module + ".rs")
        text = open(path).read()
        # Patch 1: modules live under crate::gen, not at the crate root.
        text = re.sub(r"(?m)^use crate::(\w+);$", r"use crate::gen::\1;", text)
        # Patch 2: a list of unions is boxed into a Vec of the plain type.
        if module == "parquet":
            text = replace_exactly(text, "val.push(Box::new(elem));", "val.push(elem);", 1, path)
        # Patch 3: per-method structs become public so the method table can reach them.
        for service, name, args, result in services(module, text):
            text = expose(text, args)
            text = expose(text, result)
            table.append((module, service, name, args, result))
        open(path, "w").write(text)
    if not table:
        sys.exit("postprocess: no service methods found")

    with open(os.path.join(gen, "mod.rs"), "w") as f:
        f.write(HEADER + "\n//! Rust generated by Thrift 0.24.0 from the pinned Doris IDL.\n\n")
        for module in modules:
            f.write("#[allow(clippy::all, non_camel_case_types, non_snake_case, dead_code, unused)]\n")
            f.write(f"pub mod {module};\n")
        f.write("\npub(crate) mod methods;\n")
    with open(os.path.join(gen, "methods.rs"), "w") as f:
        f.write(METHODS_PREAMBLE)
        for module, service, name, args, result in table:
            a = f"super::{module}::{args}"
            r = f"super::{module}::{result}"
            f.write(
                f'    Method {{ service: "{service}", name: "{name}",\n'
                f"        args: |i, o| roundtrip(i, o, {a}::read_from_in_protocol, {a}::write_to_out_protocol),\n"
                f"        result: |i, o| roundtrip(i, o, {r}::read_from_in_protocol, {r}::write_to_out_protocol) }},\n"
            )
        f.write("];\n")
    print(f"postprocess: {len(modules)} modules, {len(table)} methods")


if __name__ == "__main__":
    main(sys.argv[1])
